CREATE OR REPLACE FUNCTION private.admin_delete_user(p_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_target_role text; v_email text;
BEGIN
 if not private.has_module_access('users','delete','web') then raise exception 'User deletion permission required' using errcode='42501'; end if;
 if p_user_id=v_actor then raise exception 'Cannot delete the active account'; end if;
 select r.key,p.email into v_target_role,v_email from public.profiles p join public.roles r on r.id=p.role_id where p.id=p_user_id for update of p;
 if not found then raise exception 'User not found'; end if;
 if v_target_role='super_admin' or lower(v_email)='annasabbas01@gmail.com' then raise exception 'Super Admin account is protected' using errcode='42501'; end if;
 if exists(select 1 from storage.objects where owner_id=p_user_id::text) then raise exception 'User owns files; reassign ownership before deletion'; end if;
 begin
   update auth.refresh_tokens set revoked=true,updated_at=now() where user_id=p_user_id::text;
   delete from auth.users where id=p_user_id;
 exception when foreign_key_violation then
   raise exception 'User has linked records or protected history. Block this account until its references can be retained or reassigned; no records were deleted.';
 end;
 insert into public.privileged_security_events(event_type,real_actor_user_id,target_type,target_id,metadata)
 values('user.deleted',v_actor,'profile',p_user_id::text,jsonb_build_object('email',v_email,'role',v_target_role));
 return true;
END $function$

CREATE OR REPLACE FUNCTION private.admin_set_module_access(p_module_key text, p_scope text, p_target_id uuid, p_state text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_module uuid; v_role uuid; v_user uuid;
BEGIN
 if not private.is_super_admin() then raise exception 'Super Admin required' using errcode='42501'; end if;
 if p_scope is null or p_scope not in ('global','role','user') then raise exception 'Invalid scope'; end if;
 if p_state is null or p_state not in ('enabled','readonly','disabled','locked','default') then raise exception 'Invalid access state'; end if;
 select id into strict v_module from public.system_modules where key=p_module_key and is_active;
 if p_scope='global' and p_target_id is not null then raise exception 'Global scope has no target'; end if;
 if p_scope='role' then
   select id into v_role from public.roles where id=p_target_id and key<>'super_admin' and active;
   if v_role is null then raise exception 'Invalid staff role'; end if;
 elsif p_scope='user' then
   select p.id into v_user from public.profiles p join public.roles r on r.id=p.role_id where p.id=p_target_id and r.key<>'super_admin';
   if v_user is null then raise exception 'Invalid staff user'; end if;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('crm_access:'||p_module_key||':'||p_scope||':'||coalesce(p_target_id::text,''),0));
 delete from public.module_access_rules where module_id=v_module and scope_type=p_scope::public.rule_scope
 and platform='all' and role_id is not distinct from v_role and user_id is not distinct from v_user;
 if p_state<>'default' then
   insert into public.module_access_rules(module_id,scope_type,role_id,user_id,platform,access_state,created_by)
   values(v_module,p_scope::public.rule_scope,v_role,v_user,'all',p_state::public.access_state,auth.uid());
 end if;
 insert into public.privileged_security_events(event_type,real_actor_user_id,target_type,target_id,metadata)
 values('module.access_changed',auth.uid(),'module',v_module::text,jsonb_build_object('scope',p_scope,'target',p_target_id,'state',p_state));
 return true;
END $function$

CREATE OR REPLACE FUNCTION private.admin_set_role_permission(p_role_key text, p_permission_key text, p_effect text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_role uuid; v_permission uuid;
BEGIN
 if not private.is_super_admin() then raise exception 'Super Admin required' using errcode='42501'; end if;
 if p_role_key is null or p_role_key not in ('admin','manager','installer') then raise exception 'Invalid staff role'; end if;
 if p_effect is null or p_effect not in ('allow','deny') then raise exception 'Effect must be allow or deny'; end if;
 if p_effect='allow' and p_role_key='installer' and p_permission_key in ('users.create','users.block','users.delete','users.update','users.change_role','users.change_password') then
 raise exception 'Installer cannot administer accounts'; end if;
 select id into strict v_role from public.roles where key=p_role_key and active;
 select id into strict v_permission from public.permissions where key=p_permission_key;
 insert into public.role_permissions(role_id,permission_id,effect) values(v_role,v_permission,p_effect::public.permission_effect)
 on conflict(role_id,permission_id) do update set effect=excluded.effect,updated_at=now();
 insert into public.privileged_security_events(event_type,real_actor_user_id,target_type,target_id,metadata)
 values('role.permission_changed',auth.uid(),'role',v_role::text,jsonb_build_object('permission',p_permission_key,'effect',p_effect));
 return true;
END $function$

CREATE OR REPLACE FUNCTION private.admin_set_user_blocked(p_user_id uuid, p_blocked boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_role text;
BEGIN
 if p_blocked is null then raise exception 'Blocked state is required'; end if;
 if not private.has_module_access('users','block','web') then raise exception 'User blocking permission required' using errcode='42501'; end if;
 select r.key into v_role from public.profiles p join public.roles r on r.id=p.role_id where p.id=p_user_id;
 if v_role is null then raise exception 'User not found'; end if;
 return private.admin_update_user_access(p_user_id,v_role,case when p_blocked then 'blocked'::public.account_status else 'active'::public.account_status end);
END $function$

CREATE OR REPLACE FUNCTION private.admin_set_user_permission(p_user_id uuid, p_permission_key text, p_effect text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_permission uuid; v_target_role text;
BEGIN
 if not private.is_super_admin() then raise exception 'Super Admin required' using errcode='42501'; end if;
 if p_effect is null or p_effect not in ('allow','deny','default') then raise exception 'Effect must be allow, deny or default'; end if;
 select r.key into v_target_role from public.profiles p join public.roles r on r.id=p.role_id where p.id=p_user_id;
 if v_target_role is null then raise exception 'User not found'; end if;
 if v_target_role='super_admin' then raise exception 'Super Admin remains unrestricted'; end if;
 if p_effect='allow' and p_permission_key in ('users.create','users.block','users.delete','users.update','users.change_role','users.change_password') and v_target_role not in ('admin','manager')
 then raise exception 'Only Admins and Managers can receive staff administration permissions'; end if;
 select id into v_permission from public.permissions where key=p_permission_key;
 if v_permission is null then raise exception 'Unknown permission'; end if;
 if p_effect='default' then delete from public.user_permissions where user_id=p_user_id and permission_id=v_permission;
 else
   insert into public.user_permissions(user_id,permission_id,effect,granted_by)
   values(p_user_id,v_permission,p_effect::public.permission_effect,auth.uid())
   on conflict(user_id,permission_id) do update set effect=excluded.effect,granted_by=excluded.granted_by,starts_at=null,ends_at=null,updated_at=now();
 end if;
 insert into public.privileged_security_events(event_type,real_actor_user_id,target_type,target_id,metadata)
 values('user.permission_changed',auth.uid(),'profile',p_user_id::text,jsonb_build_object('permission',p_permission_key,'effect',p_effect));
 return true;
END $function$

CREATE OR REPLACE FUNCTION private.admin_update_user_access(p_user_id uuid, p_role_key text, p_status account_status)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_target_role text; v_target_status public.account_status; v_role_id uuid; v_owner boolean:=private.is_super_admin();
BEGIN
 if v_actor is null or private.current_role_key() is null then raise exception 'Active session required' using errcode='42501'; end if;
 if p_role_key is null or p_status is null then raise exception 'Role and status are required'; end if;
 select r.key,p.status into v_target_role,v_target_status from public.profiles p join public.roles r on r.id=p.role_id where p.id=p_user_id for update of p;
 if not found then raise exception 'User not found'; end if;
 if v_target_role='super_admin' and (p_role_key<>v_target_role or p_status<>'active') then raise exception 'Super Admin account is protected' using errcode='42501'; end if;
 if p_role_key='super_admin' and v_target_role<>'super_admin' then raise exception 'Additional Super Admin accounts are not permitted' using errcode='42501'; end if;
 if not v_owner then
   if p_user_id=v_actor then raise exception 'Cannot change own role or account status' using errcode='42501'; end if;
   if p_role_key<>v_target_role and not private.has_module_access('users','change_role','web') then raise exception 'User role-change permission required' using errcode='42501'; end if;
   if p_status<>v_target_status and not private.has_module_access('users','block','web') then raise exception 'User blocking permission required' using errcode='42501'; end if;
   if p_role_key=v_target_role and p_status=v_target_status and not
     (private.has_module_access('users','change_role','web') or private.has_module_access('users','block','web'))
   then raise exception 'Account management permission required' using errcode='42501'; end if;
 end if;
 select id into v_role_id from public.roles where key=p_role_key and active;
 if v_role_id is null then raise exception 'Invalid role'; end if;
 update public.profiles set role_id=v_role_id,status=p_status,
 deactivated_at=case when p_status=v_target_status then deactivated_at when p_status='deactivated' then now() else null end where id=p_user_id;
 insert into public.privileged_security_events(event_type,real_actor_user_id,effective_actor_user_id,target_type,target_id,metadata)
 values('user.access_changed',v_actor,p_user_id,'profile',p_user_id::text,
 jsonb_build_object('old_role',v_target_role,'role',p_role_key,'old_status',v_target_status,'status',p_status));
 return true;
END $function$

CREATE OR REPLACE FUNCTION private.has_module_access(p_module_key text, p_action text DEFAULT 'view'::text, p_platform platform_key DEFAULT 'web'::platform_key)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_user uuid:=auth.uid(); v_role_id uuid; v_role text:=private.current_role_key(); v_effect public.permission_effect; v_state public.access_state;
BEGIN
 if v_role is null then return false; end if;
 if private.is_super_admin() then return true; end if;
 if p_module_key='master_control' then return false; end if;
 if p_module_key='users' and p_action in ('create','block','delete','update','change_role','change_password') and v_role not in ('admin','manager') then return false; end if;
 select role_id into v_role_id from public.profiles where id=v_user;
 v_state:=private.resolve_module_state(p_module_key,p_platform);
 if v_state in ('disabled','locked') or (v_state='readonly' and p_action<>'view') then return false; end if;
 -- A role-wide revoke of account-management powers overrides a user allow.
 if p_module_key='users' and p_action in ('update','block','delete','change_role','change_password') and exists(
   select 1 from public.role_permissions rp join public.permissions pe on pe.id=rp.permission_id
   where rp.role_id=v_role_id and pe.key=p_module_key||'.'||p_action and rp.effect='deny'
 ) then return false; end if;
 select up.effect into v_effect from public.user_permissions up join public.permissions pe on pe.id=up.permission_id
 where up.user_id=v_user and pe.key=p_module_key||'.'||p_action
 and (up.starts_at is null or up.starts_at<=now()) and (up.ends_at is null or up.ends_at>now());
 if v_effect is not null then return v_effect='allow'; end if;
 select rp.effect into v_effect from public.role_permissions rp join public.permissions pe on pe.id=rp.permission_id
 where rp.role_id=v_role_id and pe.key=p_module_key||'.'||p_action;
 return coalesce(v_effect='allow',false);
END $function$

CREATE OR REPLACE FUNCTION public.end_impersonation(p_session_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_target uuid;
begin
  if (select auth.uid()) is null or not (select private.is_super_admin()) then raise exception 'Super Admin permission required' using errcode='42501'; end if;
  update public.impersonation_sessions set status='ended',ended_at=now(),ended_by=(select auth.uid())
  where id=p_session_id and real_actor_user_id=(select auth.uid()) and status='active' returning effective_actor_user_id into v_target;
  if v_target is null then return false; end if;
  insert into public.privileged_security_events(event_type,real_actor_user_id,effective_actor_user_id,impersonation_session_id)
  values('impersonation.ended',(select auth.uid()),v_target,p_session_id);
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_access_context(p_platform text DEFAULT 'web'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_user uuid := (select auth.uid());
  v_platform public.platform_key;
  v_profile jsonb;
  v_modules jsonb;
begin
  if v_user is null then raise exception 'Authentication required' using errcode='42501'; end if;
  if p_platform not in ('web','android','ios') then raise exception 'Invalid platform'; end if;
  v_platform := p_platform::public.platform_key;
  select jsonb_build_object('id',p.id,'email',p.email,'full_name',p.full_name,'status',p.status,'role',r.key,'mfa_required',p.mfa_required)
  into v_profile from public.profiles p join public.roles r on r.id=p.role_id where p.id=v_user;
  if v_profile is null or v_profile->>'status'<>'active' then raise exception 'Active profile required' using errcode='42501'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'key',m.key,'route',m.route_key,'state',private.resolve_module_state(m.key,v_platform),
    'can_view',private.has_module_access(m.key,'view',v_platform),
    'can_create',private.has_module_access(m.key,'create',v_platform),
    'can_update',private.has_module_access(m.key,'update',v_platform),
    'can_delete',private.has_module_access(m.key,'delete',v_platform),
    'can_approve',private.has_module_access(m.key,'approve',v_platform),
    'can_block',case when m.key='users' then private.has_module_access(m.key,'block',v_platform) else false end,
    'can_change_role',case when m.key='users' then private.has_module_access(m.key,'change_role',v_platform) else false end,
    'can_change_password',case when m.key='users' then private.has_module_access(m.key,'change_password',v_platform) else false end
  ) order by m.name),'[]'::jsonb)
  into v_modules from public.system_modules m where m.is_active=true and m.platform_scope in ('all'::public.platform_key,v_platform);
  return jsonb_build_object('profile',v_profile,'system_lock',private.get_effective_system_lock(v_platform),'modules',v_modules,'generated_at',now());
end;
$function$

CREATE OR REPLACE FUNCTION public.start_impersonation(p_target_user_id uuid, p_reason text, p_ticket_reference text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_id uuid; v_ttl integer;
begin
  if (select auth.uid()) is null or not (select private.is_super_admin()) then
    raise exception 'Super Admin permission required' using errcode='42501';
  end if;
  if coalesce((select auth.jwt()->>'aal'),'aal1') <> 'aal2' then
    raise exception 'MFA assurance level 2 required' using errcode='42501';
  end if;
  if nullif(trim(p_reason),'') is null then raise exception 'Reason is required'; end if;
  if p_target_user_id=(select auth.uid()) then raise exception 'Cannot impersonate self'; end if;
  if not exists(select 1 from public.profiles where id=p_target_user_id and status='active') then raise exception 'Target user is not active'; end if;
  if exists(select 1 from public.impersonation_sessions where real_actor_user_id=(select auth.uid()) and status='active' and expires_at>now()) then
    raise exception 'Nested or concurrent impersonation is not allowed';
  end if;
  select coalesce((value #>> '{}')::integer,15) into v_ttl from public.super_admin_security_settings where key='impersonation_ttl_minutes';
  v_ttl := least(greatest(coalesce(v_ttl,15),5),60);
  insert into public.impersonation_sessions(real_actor_user_id,effective_actor_user_id,reason,ticket_reference,expires_at)
  values((select auth.uid()),p_target_user_id,p_reason,p_ticket_reference,now()+make_interval(mins=>v_ttl)) returning id into v_id;
  insert into public.privileged_security_events(event_type,real_actor_user_id,effective_actor_user_id,impersonation_session_id,reason)
  values('impersonation.started',(select auth.uid()),p_target_user_id,v_id,p_reason);
  return v_id;
end;
$function$

